/// </summary>
public void modified()
{
    next modified();

    FormDataObject formDataObject = any2Object(this) as FormDataObject;
    FormDataSource  metSiteControllingAndSubordinateSetup_ds = formDataObject.datasource();
    METSiteControllingAndSubOrdinateSetup metSiteControllingAndSubOrdinateSetup = metSiteControllingAndSubordinateSetup_ds.cursor();

    metSiteControllingAndSubordinateSetup_ds.object(fieldNum(METSiteControllingAndSubOrdinateSetup, ControllingSiteId)).mandatory(!metSiteControllingAndSubOrdinateSetup.IsControllingSite);
    metSiteControllingAndSubordinateSetup_ds.object(fieldNum(METSiteControllingAndSubOrdinateSetup, ControllingSiteId)).allowEdit(!metSiteControllingAndSubOrdinateSetup.IsControllingSite);
}
